const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) {
  throw new Error('Invalid or missing session token.');
}

const requesterId = parseInt(match[1], 10);
const body = $input.first().json.body || {};

const firstName = (body.first_name || '').trim();
const lastName = (body.last_name || '').trim();
const jobTitle = (body.job_title || '').trim();
const accountId = body.account_id ? parseInt(body.account_id, 10) : null;
const email = (body.email || '').trim();
const secondaryEmail = (body.secondary_email || '').trim();
const phone = (body.phone || '').trim();
const secondaryPhone = (body.secondary_phone || '').trim();
const linkedinUrl = (body.linkedin_url || '').trim();
const city = (body.city || '').trim();
const state = (body.state || '').trim();
const zipCode = (body.zip_code || '').trim();
const country = (body.country || '').trim();
const leadStatus = (body.lead_status || 'New').trim();
const leadSource = (body.lead_source || '').trim();
const doNotContact = body.do_not_contact === true || body.do_not_contact === 'true';

if (!firstName) {
  throw new Error('"first_name" is required.');
}
if (accountId !== null && !Number.isInteger(accountId)) {
  throw new Error('"account_id" must be an integer.');
}

return [{
  json: {
    requesterId,
    first_name: firstName,
    last_name: lastName,
    job_title: jobTitle,
    account_id: accountId,
    email,
    secondary_email: secondaryEmail,
    phone,
    secondary_phone: secondaryPhone,
    linkedin_url: linkedinUrl,
    city,
    state,
    zip_code: zipCode,
    country,
    lead_status: leadStatus,
    lead_source: leadSource,
    do_not_contact: doNotContact
  }
}];
